```json
{
 "$defs": {
 "WeatherData": {
 "properties": {
 "temperature": {"title": "Temperature", "type": "number"},
 "humidity": {"title": "Humidity", "type": "number"},
 "conditions": {"title": "Conditions", "type": "string"}
 },
 "required": ["temperature", "humidity", "conditions"],
 "title": "WeatherData",
 "type": "object"
 }
 },
 "properties": {
